def run(robot):
    ids = ['2', '6']
    def hover():
        return max(0.20, max(robot.get_object_position(i)[2] for i in ids) + 0.12)
    def turn(x, y, z, skip):
        # fingers along y (0) unless a neighbour sits beside the spot on the y sides, then along x (90)
        for i in ids:
            q = robot.get_object_position(i)
            if i != skip and q[2] > z - 0.03 and abs(q[0] - x) < 0.035 and abs(q[1] - y) < 0.08:
                robot.rotate_gripper(90)
                return
        robot.rotate_gripper(0)
    p = robot.get_object_position('2')
    h = hover()
    g = robot.get_gripper_position()
    robot.move_to(g[0], g[1], h)
    robot.move_to(p[0], p[1], h)
    robot.move_to(p[0], p[1], p[2] + 0.18)
    robot.rotate_gripper(150)

